fun rowKey(merchantId: String, at: Instant, paymentId: String): String {
    // later time -> smaller number -> sorts first
    val reversed = Long.MAX_VALUE - at.toEpochMilli()
    // fixed width: as text, "10" sorts before "9", so every number needs the same length
    return "$merchantId#${"%019d".format(reversed)}#$paymentId"
}
